using System; using Microsoft.VisualStudio.TestTools.UnitTesting; using TaskTree.Core.Enums; using TaskTree.Core.Models; using TaskTree.Modules.Snooze;
namespace TaskTree.Modules.Snooze.Tests{[TestClass]public class EscalationPolicyEvaluatorTests{static readonly DateTimeOffset T=new(2026,6,1,12,0,0,TimeSpan.Zero);static SnoozeState S(DateTimeOffset until)=>new(Guid.NewGuid(),until,SnoozeReason.UserRequested,T,T);[TestMethod]public void ShouldEscalate_NoSnooze_ReturnsFalse()=>Assert.IsFalse(EscalationPolicyEvaluator.ShouldEscalate(null,T,EscalationPolicy.Default,0));[TestMethod]public void ShouldEscalate_RepeatBelowMax_ReturnsFalse()=>Assert.IsFalse(EscalationPolicyEvaluator.ShouldEscalate(S(T.AddMinutes(5)),T,EscalationPolicy.Default,1));[TestMethod]public void ShouldEscalate_RepeatAtMax_ReturnsTrue()=>Assert.IsTrue(EscalationPolicyEvaluator.ShouldEscalate(S(T.AddMinutes(5)),T,EscalationPolicy.Default,3));[TestMethod]public void ShouldEscalate_ExpiredSnooze_ReturnsTrue()=>Assert.IsTrue(EscalationPolicyEvaluator.ShouldEscalate(S(T.AddMinutes(-1)),T,EscalationPolicy.Default,0));[TestMethod]public void ShouldEscalate_ActiveSnooze_ReturnsFalse()=>Assert.IsFalse(EscalationPolicyEvaluator.ShouldEscalate(S(T.AddMinutes(5)),T,EscalationPolicy.Default,0));[TestMethod]public void ShouldEscalate_NullPolicy_Throws()=>Assert.ThrowsException<ArgumentNullException>(()=>EscalationPolicyEvaluator.ShouldEscalate(S(T),T,null!,0));}}
